function t(en,hi){return state.language==='hi'?hi:en;}
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),3800);}
function btn(label,action,kind='',ic=''){return `<button class="btn ${kind}" data-action="${action}">${ic?icon(ic):''}${label}</button>`;}
function pill(risk,label){return `<span class="pill ${risk}">${icon(risk==='high'?'alert':risk==='medium'?'info':risk==='low'?'checkCircle':'clock')}${esc(label||({low:'No strong indicators',high:'High risk',medium:'Needs review'}[risk])||risk)}</span>`;}
