 const consumerNav=[['home',t('Home','होम'),'home'],['check',t('Check Payment','भुगतान जाँचें'),'scan'],['activity',t('Activity','गतिविधि'),'activity'],['settings',t('Settings','सेटिंग्स'),'settings']];
