function recentTable(records){if(!records.length)return `<div class="empty">${icon('activity')}<h2>${t('Your first check starts here','अपनी पहली जाँच करें')}</h2><p>${t('Payment checks will appear here.','भुगतान जाँच यहाँ दिखेंगी।')}</p>${btn(t('Check a payment','भुगतान जाँचें'),'new-check')}</div>`;return `<table class="recent-table"><thead><tr><th>${t('Recipient','प्राप्तकर्ता')}</th><th>${t('Amount','राशि')}</th><th class="time-column">${t('Checked','जाँच का समय')}</th><th>${t('Assessment','आकलन')}</th></tr></thead><tbody>${records.map(r=>`<tr data-record="${r.id}" tabindex="0" role="button" aria-label="${esc(r.recipient)}, ${money(r.amount)}, ${esc(r.risk)} risk"><td><div class="recipient-cell"><span class="merchant-icon ${r.risk==='high'?'red':r.risk==='medium'?'blue':''}">${icon(scenarios.find(s=>s.id===r.scenario)?.icon||'store')}</span><span><strong>${esc(r.recipient)}</strong><small>${esc(r.action)}</small></span></div></td><td class="amount">${money(r.amount)}</td><td class="time-column"><small style="color:var(--muted);font-size:10px">${dateText(r.time)}</small></td><td>${pill(r.invalidated?'neutral':r.risk,r.invalidated?'Recheck required':r.risk==='low'?t('No strong indicators','कोई प्रबल संकेत नहीं'):r.risk==='high'?t('High risk','उच्च जोखिम'):t('Needs review','समीक्षा आवश्यक'))}</td></tr>`).join('')}</tbody></table>`;}
function createFlow(id,variation){const base=scenarios.find(s=>s.id===id)||scenarios[0];flow={...base,originalAmount:base.amount,link:'https://pay.demo/'+base.id,currency:'INR',session:crypto.randomUUID(),intent:'',message:base.message};if(variation==='proprietor'){flow.recipient='Rajesh Sharma';flow.reference='Approved proprietor variation for Sharma Medical';flow.variation=true;}if(variation==='unknown'){flow.recipient='Neighbourhood Books';flow.account='neighbourbooks@demo';flow.expected='Neighbourhood Books';flow.ref='unavailable';flow.reference='No independent merchant record';flow.risk='medium';flow.category='Identity unavailable';flow.purpose='Book purchase';flow.message='Please pay ₹450 for your books.';flow.id='unknown';}assessment=null;formError='';missingContext=false;flowStep='input';page='check';closeModal(false);render();window.scrollTo(0,0);}
function flowFields(){if(!flow)return '';return `<div class="form-row"><div class="section-heading" style="margin-top:0"><h3>${t('Payment details','भुगतान विवरण')}</h3><span class="pill neutral">${icon('info')}Synthetic demo</span></div><div class="field-grid"><div class="detail-pair"><small>${t('Recipient','प्राप्तकर्ता')}</small><strong>${esc(flow.recipient)}</strong></div><div class="detail-pair"><small>${t('Amount','राशि')}</small><strong>${money(flow.amount)}</strong></div><div class="detail-pair"><small>${t('Payment direction','भुगतान की दिशा')}</small><strong>${t('Outgoing · money leaves your account','पैसे आपके खाते से जाएंगे')}</strong></div><div class="detail-pair"><small>${t('Purpose','उद्देश्य')}</small><strong>${esc(flow.purpose)}</strong></div><div class="detail-pair"><small>${t('Demo account','डेमो खाता')}</small><strong>${esc(flow.account)}</strong></div><div class="detail-pair"><small>${t('Independent merchant reference','स्वतंत्र व्यापारी रिकॉर्ड')}</small><strong>${esc(flow.reference)}</strong></div></div></div>`;}
function stepper(step){return `<div class="stepper" aria-label="Assessment progress"><div class="step ${step===1?'active':''}"><b>1</b>${t('Add payment','भुगतान जोड़ें')}</div><span></span><div class="step ${step===2?'active':''}"><b>2</b>${t('Understand','समझें')}</div><span></span><div class="step ${step===3?'active':''}"><b>3</b>${t('Review','समीक्षा करें')}</div></div>`;}
function checkPage(){
 if(flowStep==='loading')return `<div class="flow-container">${stepper(2)}<div class="card loading" role="status"><div class="spinner"></div><h2>${t('Connecting the dots…','विवरण जाँचे जा रहे हैं…')}</h2><p>${t('Checking the payment against the information you shared.','आपके दिए विवरण से भुगतान की तुलना की जा रही है।')}</p><div class="progress-item">${icon('checkCircle')}${t('Reading demo payment details','डेमो भुगतान विवरण पढ़ना')}</div><div class="progress-item">${icon('lock')}${t('No bank connection. No real payment.','कोई बैंक कनेक्शन या वास्तविक भुगतान नहीं।')}</div></div></div>`;
 if(flowStep==='intent')return intentScreen();if(flowStep==='result')return resultScreen();if(flowStep==='identity')return identityScreen();if(flowStep==='changed')return changeScreen();if(flowStep==='verify')return verifyScreen();if(flowStep==='complete')return completeScreen();
 return `<div class="flow-container"><button class="back" data-page="home">${icon('back')}${t('Back to home','होम पर वापस')}</button><div class="flow-heading"><h1>${t('Understand before you pay.','भुगतान से पहले समझें।')}</h1><p>${t('Add a demo payment. We’ll help you look at the details.','एक डेमो भुगतान जोड़ें। हम विवरण समझने में मदद करेंगे।')}</p></div>${stepper(1)}<div class="card form-card"><div class="tabs" role="tablist" aria-label="Payment input mode">${[['qr','scan',t('Scan QR','QR स्कैन')],['link','link',t('Payment link','भुगतान लिंक')],['request','message',t('Payment request','भुगतान अनुरोध')]].map(([id,ic,label])=>`<button class="tab ${mode===id?'active':''}" role="tab" aria-selected="${mode===id}" data-mode="${id}">${icon(ic)}${label}</button>`).join('')}</div>
 <form id="check-form"><div role="tabpanel">${mode==='qr'?`<button type="button" class="upload-area" data-action="qr-picker">${icon('scan')}<strong>${flow?t('Demo QR ready to review','डेमो QR समीक्षा के लिए तैयार'):t('Scan a demo QR','एक डेमो QR स्कैन करें')}</strong><small>${t('Choose a synthetic QR to simulate scanning','स्कैन का अनुकरण करने के लिए एक डेमो QR चुनें')}</small><span class="text-link">${t('Open demo scanner','डेमो स्कैनर खोलें')}${icon('arrow')}</span></button>`:mode==='link'?`<label class="field-label" for="payment-link">${t('Demo payment link','डेमो भुगतान लिंक')}</label><div class="input-wrap">${icon('link')}<input name="link" id="payment-link" value="${esc(flow?.link||'')}" placeholder="https://pay.demo/refund" autocomplete="off"></div><button class="text-link" type="button" data-action="load-link" style="margin-top:7px">${t('Read link details','लिंक विवरण पढ़ें')}${icon('arrow')}</button><p style="font-size:10px;color:var(--muted);margin-top:7px">Try https://pay.demo/merchant or https://pay.demo/refund</p>`:`<label for="request-select" class="field-label">${t('Select a simulated payment request','एक डेमो भुगतान अनुरोध चुनें')}</label><select id="request-select" name="scenario"><option value="">${t('Choose a demo request…','एक डेमो अनुरोध चुनें…')}</option>${scenarios.map(s=>`<option value="${s.id}" ${flow?.id===s.id?'selected':''}>${esc(s.name)} · ${money(s.amount)}</option>`).join('')}</select>`}
 ${flowFields()}<div class="form-row"><label for="payment-message" class="field-label">${t('What led to this payment?','इस भुगतान का कारण क्या है?')} <span class="optional">${t('(optional)','(वैकल्पिक)')}</span></label><textarea name="message" id="payment-message" placeholder="${t('Paste a demo message for more context…','संदर्भ के लिए डेमो संदेश पेस्ट करें…')}">${esc(flow?.message||'')}</textarea><small style="font-size:9px;color:var(--muted)">${t('Only the message you provide here is used.','केवल यहाँ दिया गया संदेश इस्तेमाल होता है।')}</small></div>
 ${missingContext?`<div class="form-row"><h3>${t('What are you trying to do?','आप क्या करना चाहते हैं?')}</h3><div class="radio-options">${[['receive',t('Receive money','पैसे पाना')],['pay',t('Pay someone','भुगतान करना')],['verify',t('Verify my account','खाता सत्यापित करना')]].map(([value,label])=>`<label><input type="radio" name="intent" value="${value}" ${flow?.intent===value?'checked':''}>${label}</label>`).join('')}</div></div>`:''}
 ${formError?`<p role="alert" class="error">${esc(formError)}</p>`:''}<div class="info-note">${icon('lock')}<span>${t('This is a demo. We never open a payment app or ask for your UPI PIN, OTP, or bank credentials.','यह डेमो है। हम UPI PIN, OTP या बैंक की जानकारी नहीं माँगते।')}</span></div><div class="button-row"><button type="button" class="btn secondary" data-action="scenarios">${t('Try a scenario','डेमो चुनें')}</button><button type="submit" class="btn">${t('Check payment','भुगतान जाँचें')}${icon('arrow')}</button></div></div></form></div></div>`;
}
function binding(f){return JSON.stringify([f.amount,f.account,f.recipient,f.currency,f.session,f.message,f.intent]);}
function validAssessment(){return assessment&&flow&&assessment.binding===binding(flow)&&!assessment.invalidated;}
function currentEvidence(){
 const message=flow.message||'';const refund=/\brefund\b|\breceive\b|रिफंड|वापस/i.test(message);
 let risk=flow.risk,category=flow.category,evidence=[];
 if(flow.changed){risk='high';category='Recipient changed';evidence=['The recipient changed after the previous assessment.','The new destination differs from the shop’s saved demo record.'];}
 else if(flow.id==='refund') {risk=refund||flow.intent==='receive'?'high':'medium';category=risk==='high'?'Refund deception':'Missing context';evidence=['First payment to this recipient.',...(refund?['The supplied message appears to promise incoming money.']:flow.intent==='receive'?['You said you expect to receive money.']:['The original refund context is no longer available.']),'This transaction sends money from the account.'];}
 else if(flow.id==='qr'){evidence=['QR destination differs from Campus Canteen’s independent saved demo record.','The name displayed inside the QR is not independent verification.'];}
 else if(flow.id==='kyc'){evidence=[/kyc|closes|closure|verify/i.test(message)?'The supplied message appears to threaten closure and request a KYC fee.':'The original KYC message is unavailable; its interpretation is uncertain.','The recipient is unrelated to the expected account service.','Independent recipient identity is unavailable.'];}
 else if(flow.id==='remote'){evidence=['Screen sharing is active (simulated device signal).','First payment to this recipient.'];}
 else if(flow.id==='job'){evidence=[/deposit|onboarding/i.test(message)?'The supplied job message requests an upfront refundable deposit.':'The original job-deposit message is no longer available.','Independent employer identity is unavailable.'];}
 else if(flow.ref==='unavailable'){evidence=['No independent merchant reference is available.','The QR recipient name cannot verify itself.'];}
 else{evidence=[flow.variation?'The account matches the shop’s saved record; Rajesh Sharma is an approved proprietor-name variation.':'Destination matches the independent saved demo record.','Amount and payment direction match the demo purchase.'];}
 if((refund||flow.intent==='receive')&&risk==='low'){risk='high';category='Intent mismatch';evidence.push(refund?'The supplied message appears to promise incoming money.':'You said you expect to receive money.','This transaction sends money from the account.');}
 if(flow.originalAmount&&flow.amount!==flow.originalAmount){if(risk==='low'){risk='medium';category='Amount changed';}evidence=evidence.filter(e=>!e.startsWith('Amount and payment direction'));evidence.push('The amount differs from the original demo request of '+money(flow.originalAmount)+'.');}
 if(flow.amount>10000){risk='high';if(!refund)category='Unusual amount';evidence.push('Amount is higher than this synthetic customer’s usual payment range.');}
 return {risk,category,evidence,refund:refund||flow.intent==='receive'};
}
async function analyse(){
 if(!flow){formError=t('Choose a demo QR, link, or payment request first.','पहले एक डेमो QR, लिंक या भुगतान अनुरोध चुनें।');render();return;}
 if(!flow.message.trim()&&!flow.intent){missingContext=true;formError=t('A little context will help. Choose what you’re trying to do.','कृपया चुनें कि आप क्या करना चाहते हैं।');render();return;}
 missingContext=false;flowStep='loading';const token=++run;const snapshot=binding(flow);render();await new Promise(r=>setTimeout(r,1050));if(token!==run||snapshot!==binding(flow))return;
 const finding=currentEvidence();const record={id:'UG-'+String(Date.now()).slice(-7),scenario:flow.id,recipient:flow.recipient,account:flow.account,amount:flow.amount,currency:flow.currency,risk:finding.risk,category:finding.category,evidence:finding.evidence,message:flow.message,action:'Reviewed',review:'Pending review',customer:'Aarav Mehta',time:Date.now(),session:flow.session,reference:flow.ref,expected:flow.expected,purpose:flow.purpose};
 state.records.unshift(record);persist();assessment={...finding,binding:snapshot,recordId:record.id};flowStep=finding.refund&&finding.risk==='high'?'intent':'result';render();if(state.readAloud&&flowStep==='result')readAloud();
}
function intentScreen(){const messagePromise=/\brefund\b|\breceive\b|रिफंड|वापस/i.test(flow.message);return `<div class="flow-container"><button class="back" data-action="back-input">${icon('back')}${t('Back to payment details','भुगतान विवरण पर वापस')}</button>${stepper(2)}<div class="flow-heading"><h1>${t('The message and payment don’t match.','संदेश और भुगतान में अंतर है।')}</h1><p>${t('Let’s put what you expect beside what will actually happen.','आपकी उम्मीद और वास्तविक भुगतान की तुलना करें।')}</p></div><div class="compare-grid"><div class="compare-card promise"><small>${messagePromise?t('WHAT THE MESSAGE APPEARS TO PROMISE','संदेश में क्या वादा दिखता है'):t('WHAT YOU EXPECT','आपकी उम्मीद')}</small><h2>${t('Receive','आपको मिलेंगे')} ${money(flow.amount)} ${messagePromise?t('as a refund.','रिफंड।'):t('as an incoming payment.','भुगतान।')}</h2><p>${messagePromise?t('Message interpretation · uncertain, based only on supplied text.','संदेश का अनुमानित अर्थ · केवल दिए गए पाठ पर आधारित।'):t('Based on the intention you selected.','आपके चुने हुए उद्देश्य पर आधारित।')}</p></div><div class="compare-card actual"><small>${t('WHAT THIS PAYMENT DOES','यह भुगतान क्या करता है')}</small><h2>${t('Send','भेजें')} ${money(flow.amount)} ${t('to','को')} ${esc(flow.recipient)}.</h2><p>${t('Observed payment details · outgoing payment.','देखे गए भुगतान विवरण · पैसे बाहर जाएंगे।')}</p></div></div><div class="warning-banner">${icon('alert')}<span>${t('Receiving money and sending money are opposite actions. This payment will take money out of your account.','पैसे पाना और पैसे भेजना विपरीत हैं। इस भुगतान से आपके खाते से पैसे जाएंगे।')}</span></div><div class="card form-card" style="margin-top:20px"><h3>${t('What brought this to our attention','इन संकेतों पर ध्यान दें')}</h3>${evidenceList(assessment.evidence)}${btn(t('Review payment warning','भुगतान की चेतावनी देखें'),'show-result','full','arrow')}</div></div>`;}
function evidenceList(items){return `<ul class="evidence-list">${items.map(text=>`<li>${icon(/appears|interpretation/i.test(text)?'info':'checkCircle')}<span>${esc(text)}${/appears|interpretation/i.test(text)?'<small class="evidence-kind">Inferred from supplied text · not a confirmed fact</small>':text.includes('simulated')?'<small class="evidence-kind">Simulated device signal</small>':''}</span></li>`).join('')}</ul>`;}
function resultScreen(){
 if(!validAssessment()){flowStep='changed';return changeScreen();}
 const {risk,category,evidence,refund}=assessment;
 const title=risk==='low'?t('No strong risk indicators detected.','कोई प्रबल जोखिम संकेत नहीं मिला।'):refund?t(`You are about to PAY ${money(flow.amount)}—not receive a refund.`,`इस भुगतान से आपके खाते से ${money(flow.amount)} जाएंगे। आपको पैसे नहीं मिलेंगे।`):category==='Recipient changed'?t('The payment destination has changed.','भुगतान का प्राप्तकर्ता बदल गया है।'):category==='QR substitution'?t('This QR points to a different account.','यह QR एक अलग खाते पर जाता है।'):category==='Remote access'?t('Pause this payment. Screen sharing is active.','रुकें। स्क्रीन शेयरिंग चालू है।'):category==='Fake KYC'?t('This account-verification request needs a closer look.','इस खाता सत्यापन अनुरोध की जाँच करें।'):category==='Unusual amount'?t('Check this unusually large payment.','इस असामान्य बड़ी राशि की जाँच करें।'):t('A little more verification is needed.','थोड़ी और जाँच की ज़रूरत है।');
 const sub=risk==='low'?t('The supplied details are consistent with this demo purchase. This assessment is not a guarantee.','दिए गए विवरण डेमो खरीदारी से मेल खाते हैं। यह कोई गारंटी नहीं है।'):refund?t('This transaction sends money from your account. The attached message appears to promise a refund.','यह भुगतान आपके खाते से पैसे भेजता है। संदेश में रिफंड का वादा दिखता है।'):t('Review the specific signals below before deciding what to do next.','अगला कदम चुनने से पहले नीचे दिए गए संकेत पढ़ें।');
 return `<div class="flow-container"><button class="back" data-action="back-input">${icon('back')}${t('Back to payment details','भुगतान विवरण पर वापस')}</button>${stepper(3)}<div class="assessment-header"><div class="status-icon ${risk}">${icon(risk==='low'?'shield':risk==='high'?'alert':'info')}</div>${pill(risk)}<h1 style="margin-top:13px">${esc(title)}</h1><p>${sub}</p><button class="read-aloud" data-action="read-aloud">${icon('volume')}${t('Read warning aloud','चेतावनी सुनें')}</button></div><section class="card money-card"><span class="money-meta">${t('AMOUNT LEAVING YOUR ACCOUNT','आपके खाते से जाने वाली राशि')}</span><div class="money-value">${money(flow.amount)}</div><div class="field-grid"><div class="detail-pair"><small>${t('Recipient','प्राप्तकर्ता')}</small><strong>${esc(flow.recipient)}</strong></div><div class="detail-pair"><small>${t('Payment direction','भुगतान दिशा')}</small><strong>${t('Outgoing payment · INR','बाहर जाने वाला भुगतान · INR')}</strong></div><div class="detail-pair"><small>${t('Demo account','डेमो खाता')}</small><strong>${esc(flow.account)}</strong></div><div class="detail-pair"><small>${t('Assessment','आकलन')}</small><strong>${esc(category)}</strong></div></div>${evidenceList(evidence)}<details class="explain"><summary>${t('Why am I seeing this?','यह चेतावनी क्यों दिख रही है?')}</summary><p>${t('We compare your supplied payment details with your message and available independent demo records. Message meaning is an interpretation; account, amount, and payment direction come from the synthetic payment. No private messages or live bank data are accessed.','आपके दिए गए भुगतान विवरण, संदेश और उपलब्ध स्वतंत्र डेमो रिकॉर्ड की तुलना होती है। संदेश का अर्थ अनुमान है। किसी निजी संदेश या बैंक डेटा तक पहुँच नहीं है।')}</p><p>${t('This check applies to this amount, destination, currency, and demo session. Any change requires a new check.','यह जाँच केवल इस राशि, प्राप्तकर्ता, मुद्रा और डेमो सत्र पर लागू है। बदलाव पर फिर से जाँच ज़रूरी है।')}</p></details></section>
 <div class="assessment-actions">${risk==='low'?btn(t('Continue to demo preview','डेमो पूर्वावलोकन पर जाएँ'),'verify','full'):btn(t('Cancel payment','भुगतान रद्द करें'),'cancel-payment','danger full')}${risk==='low'?btn(t('Review merchant identity','व्यापारी की पहचान देखें'),'identity','secondary full'):btn(t('Review details','विवरण देखें'),'verify','secondary full')}${flow.id==='change'&&!flow.changed?btn(t('Simulate recipient change','प्राप्तकर्ता बदलकर देखें'),'change-recipient','quiet full','refresh'):''}<button class="subtle-link" data-action="edit-details">${t('Edit demo payment details','डेमो भुगतान विवरण बदलें')}</button></div></div>`;
}
function identityScreen(){let match=flow.ref==='match';return `<div class="flow-container"><button class="back" data-action="show-result">${icon('back')}${t('Back to assessment','आकलन पर वापस')}</button><div class="flow-heading"><h1>${t('Who’s behind this QR?','इस QR का प्राप्तकर्ता कौन है?')}</h1><p>${t('A name in a QR is a claim. A separate saved record helps us compare destinations.','QR में लिखा नाम दावा है। अलग रिकॉर्ड से खाते की तुलना होती है।')}</p></div><div class="card form-card"><div class="identity-row"><div><small>${t('Expected merchant','अपेक्षित व्यापारी')}</small><strong>${esc(flow.expected)}</strong></div>${icon('store')}</div><div class="identity-row"><div><small>${t('Recipient extracted from QR','QR से मिला प्राप्तकर्ता')}</small><strong>${esc(flow.recipient)}</strong><small style="margin-top:5px">${esc(flow.account)}</small></div>${pill('neutral','QR claim')}</div><div class="identity-row"><div><small>${t('Independent saved demo record','स्वतंत्र डेमो रिकॉर्ड')}</small><strong>${flow.ref==='match'?'sharmamedical@demo':flow.ref==='mismatch'?'campuscanteen@demo':t('No verified record available','कोई सत्यापित रिकॉर्ड उपलब्ध नहीं')}</strong></div>${pill(match?'low':flow.ref==='mismatch'?'high':'medium',match?'Destination matches':flow.ref==='mismatch'?'Destination differs':'Unavailable')}</div>${flow.variation?`<div class="info-note" style="margin-top:18px">${icon('info')}Rajesh Sharma is an approved proprietor-name variation in the separate demo record. The destination account matches Sharma Medical.</div>`:''}<div class="${match?'info-note':'warning-banner'}" style="margin-top:20px">${icon(match?'checkCircle':'info')}<span>${match?t('The destination matches the independent saved demo record. This does not guarantee the payment is safe.','प्राप्तकर्ता स्वतंत्र डेमो रिकॉर्ड से मेल खाता है। यह सुरक्षा की गारंटी नहीं है।'):flow.ref==='mismatch'?t('This QR sends money to a different account from the shop’s saved record.','यह QR दुकान के सेव किए गए रिकॉर्ड से अलग खाते में पैसे भेजता है।'):t('We cannot independently confirm this merchant. Check the destination with the shop through a separate, trusted channel.','व्यापारी की स्वतंत्र पुष्टि नहीं हो सकी। दुकान से अलग भरोसेमंद माध्यम से खाते की पुष्टि करें।')}</span></div><div class="button-row">${btn(t('Back to assessment','आकलन पर वापस'),'show-result','secondary')}${btn(t('Review next step','अगला कदम देखें'),'verify')}</div></div></div>`;}
function verifyScreen(){if(!validAssessment()){flowStep='changed';return changeScreen();}const risk=assessment.risk;let question,body;
 if(assessment.refund){question=t('Are you expecting to receive money?','क्या आप पैसे मिलने की उम्मीद कर रहे हैं?');body=t('This payment sends money. If you expect a refund, cancel it and contact the sender independently. Trust in the sender does not resolve this contradiction.','यह भुगतान पैसे भेजता है। रिफंड की उम्मीद है तो रद्द करें और अलग माध्यम से संपर्क करें। भरोसा इस विरोधाभास को नहीं बदलता।');}
 else if(flow.id==='remote'){question=t('Stop screen sharing before continuing.','आगे बढ़ने से पहले स्क्रीन शेयरिंग बंद करें।');body=t('Device signal: simulated screen sharing is active. Stop it in this demo, then run a fresh check.','डिवाइस संकेत: डेमो स्क्रीन शेयरिंग चालू है। इसे बंद करके फिर जाँचें।');}
 else if(flow.ref==='mismatch'||flow.changed){question=t('Confirm the recipient independently with the shop.','दुकान से अलग माध्यम से प्राप्तकर्ता की पुष्टि करें।');body=t('The destination differs from the saved demo record. Do not rely on the name in the QR. A simple “I trust this person” cannot remove this mismatch.','प्राप्तकर्ता सेव किए गए रिकॉर्ड से अलग है। QR के नाम पर निर्भर न रहें।');}
 else if(risk==='medium'){question=t('Can you verify this request independently?','क्या आप इस अनुरोध की स्वतंत्र पुष्टि कर सकते हैं?');body=t('An independent identity record is unavailable. This case stays in analyst review; choosing to trust the sender will not remove the missing evidence.','स्वतंत्र पहचान रिकॉर्ड उपलब्ध नहीं है। यह मामला विश्लेषक समीक्षा में रहेगा।');}
 else if(risk==='high'){question=t('Check the amount and recipient.','राशि और प्राप्तकर्ता जाँचें।');body=t('The warning remains until the details or evidence change and a fresh check is completed.','विवरण या साक्ष्य बदलने और फिर से जाँच होने तक चेतावनी बनी रहेगी।');}
 else{question=t('Take one last look.','एक बार फिर जाँचें।');body=t('You are sending money to the recipient below. Continuing only simulates a completion in this demo.','आप नीचे दिए प्राप्तकर्ता को पैसे भेजने का डेमो करेंगे। कोई असली भुगतान नहीं होगा।');}
 return `<div class="flow-container"><button class="back" data-action="show-result">${icon('back')}${t('Back to assessment','आकलन पर वापस')}</button><div class="flow-heading"><h1>${question}</h1><p>${body}</p></div><div class="card form-card">${flowFields()}${risk==='low'?`<div class="info-note">${icon('info')}${t('No strong risk indicators detected. Always confirm the destination yourself.','कोई प्रबल जोखिम संकेत नहीं मिला। प्राप्तकर्ता की पुष्टि स्वयं करें।')}</div>`:`<div class="warning-banner">${icon('alert')}<span>${t('This assessment still needs your attention. No real payment can be made here.','इस आकलन पर ध्यान दें। यहाँ कोई वास्तविक भुगतान नहीं हो सकता।')}</span></div>`}<div class="assessment-actions">${risk==='low'?btn(t('Simulate payment completion','भुगतान पूरा होने का डेमो करें'),'complete-payment','full','checkCircle'):btn(t('Cancel payment','भुगतान रद्द करें'),'cancel-payment','danger full')}${flow.id==='remote'&&!flow.stoppedSharing?btn(t('Stop simulated screen sharing & recheck','डेमो स्क्रीन शेयरिंग बंद करें और फिर जाँचें'),'stop-sharing','secondary full'):''}${flow.ref==='mismatch'||flow.ref==='unavailable'?btn(t('Compare merchant identity','व्यापारी की पहचान तुलना करें'),'identity','secondary full'):''}${flow.id==='change'&&!flow.changed?btn(t('Simulate recipient change','प्राप्तकर्ता बदलकर देखें'),'change-recipient','quiet full','refresh'):''}${risk!=='low'?btn(t('Record for review & return home','समीक्षा के लिए दर्ज करें और होम पर जाएँ'),'leave-review','secondary full'):''}</div></div></div>`;}
function changeScreen(){return `<div class="flow-container"><button class="back" data-action="back-input">${icon('back')}${t('Back to payment details','भुगतान विवरण पर वापस')}</button><div class="assessment-header"><div class="status-icon medium">${icon('refresh')}</div><h1>${t('Payment details changed','भुगतान विवरण बदल गए')}</h1><p>${t('The recipient changed after your safety check. Review the new details.','जाँच के बाद प्राप्तकर्ता बदल गया। नए विवरण की समीक्षा करें।')}</p></div><div class="change-comparison"><div><small>${t('PREVIOUS RECIPIENT','पिछला प्राप्तकर्ता')}</small><strong>${esc(flow?.oldRecipient||'Sharma Medical')}</strong><p style="font-size:10px;color:var(--muted);margin-top:5px">sharmamedical@demo</p></div><div><small>${t('NEW RECIPIENT','नया प्राप्तकर्ता')}</small><strong>${esc(flow?.recipient||'Amit Personal')}</strong><p style="font-size:10px;color:var(--muted);margin-top:5px">${esc(flow?.account||'amitpersonal@demo')}</p></div></div><div class="warning-banner">${icon('alert')}<span>${t('Your previous assessment is no longer valid. A new check is required before you can continue.','पिछला आकलन अब मान्य नहीं है। आगे बढ़ने से पहले फिर से जाँच ज़रूरी है।')}</span></div><div class="button-row">${btn(t('Cancel payment','भुगतान रद्द करें'),'cancel-payment','secondary')}${btn(t('Check new details','नए विवरण जाँचें'),'reassess','','refresh')}</div></div>`;}
function completeScreen(){const cancelled=flow?.outcome==='Cancelled';return `<div class="flow-container"><div class="card complete-card"><div class="status-icon">${icon(cancelled?'shield':'checkCircle')}</div><h1>${cancelled?t('Payment cancelled. You’re in control.','भुगतान रद्द। फैसला आपका है।'):t('Demo complete. Details understood.','डेमो पूरा। विवरण समझ लिए गए।')}</h1><p>${cancelled?t('No money was sent. This check and your cancellation are saved in demo activity and the analyst dashboard.','कोई पैसे नहीं भेजे गए। जाँच और रद्द करने की जानकारी डेमो गतिविधि व विश्लेषक डैशबोर्ड में सेव है।'):t('No money moved. This simulated completion is saved in your demo activity.','कोई वास्तविक भुगतान नहीं हुआ। डेमो गतिविधि में इसे सेव कर दिया गया है।')}</p><div class="field-grid"><div class="detail-pair"><small>${t('Recipient','प्राप्तकर्ता')}</small><strong>${esc(flow.recipient)}</strong></div><div class="detail-pair"><small>${t('Amount','राशि')}</small><strong>${money(flow.amount)}</strong></div></div><div class="button-row" style="justify-content:center">${btn(t('Back to home','होम पर वापस'),'go-home')}${btn(t('View activity','गतिविधि देखें'),'go-activity','secondary')}</div><button class="text-link" data-action="open-analyst-record" style="margin-top:20px">${t('See connected analyst record','जुड़ा हुआ विश्लेषक रिकॉर्ड देखें')}${icon('arrow')}</button></div></div>`;}
function activity(){const records=state.records.filter(r=>r.customer==='Aarav Mehta'&&(activityFilter==='all'||r.action===activityFilter));return `<div class="page-head"><div><h1>${t('Your payment checks','आपकी भुगतान जाँच')}</h1><p>${t('A little history. A clearer picture. All synthetic demo data.','जाँच का इतिहास। सभी विवरण डेमो हैं।')}</p></div>${btn(t('New check','नई जाँच'),'new-check','','scan')}</div><div class="activity-filters">${[['all',t('All checks','सभी जाँच')],['Cancelled',t('Cancelled','रद्द')],['Reviewed',t('Reviewed','समीक्षित')],['Simulated completion',t('Demo completed','डेमो पूरा')]].map(([id,label])=>`<button data-activity-filter="${id}" class="${activityFilter===id?'active':''}">${label}</button>`).join('')}</div><div class="card table-scroll">${recentTable(records)}</div><p class="privacy">${icon('lock')}${t('Saved only in this browser. Reset your demo data in Settings.','केवल इस ब्राउज़र में सेव। सेटिंग्स से डेमो डेटा रीसेट करें।')}</p>${footer()}`;}
function settings(){return `<div class="flow-container"><div class="page-head"><div><h1>${t('Make it feel like you.','अपनी पसंद के अनुसार।')}</h1><p>${t('Your preferences. Your clarity.','आपकी पसंद। आपकी स्पष्टता।')}</p></div></div><div class="card settings-group"><h2>${t('Language & accessibility','भाषा और सुलभता')}</h2><div class="setting-row"><div><strong>${t('App language','ऐप की भाषा')}</strong><p>${t('Key payment screens and warnings.','मुख्य भुगतान स्क्रीन और चेतावनियाँ।')}</p></div><div class="language-options"><button data-language="en" class="${state.language==='en'?'active':''}">English</button><button data-language="hi" class="${state.language==='hi'?'active':''}">हिन्दी</button></div></div>${toggleSetting('readAloud',t('Read warnings aloud','चेतावनी पढ़कर सुनाएँ'),t('Use your browser’s available voices.','ब्राउज़र में उपलब्ध आवाज़ का उपयोग करें।'))}${toggleSetting('largeText',t('Larger text','बड़ा पाठ'),t('Make explanations easier to read.','जानकारी पढ़ना आसान बनाएँ।'))}${toggleSetting('contrast',t('Higher contrast','अधिक कंट्रास्ट'),t('Stronger text and card boundaries.','पाठ और कार्ड की सीमाएँ स्पष्ट करें।'))}</div><div class="card settings-group"><h2>${t('Your information stays yours.','आपकी जानकारी आपकी है।')}</h2><p style="font-size:12px;color:var(--muted);line-height:1.9">${t('Only demo details you deliberately provide are used. We don’t access your other apps, private messages, bank account, camera, or contacts. Demo records and preferences are stored in this browser. No real AI model or bank connection is used.','केवल आपके दिए गए डेमो विवरण इस्तेमाल होते हैं। दूसरे ऐप, निजी संदेश, बैंक खाते, कैमरा या संपर्कों तक पहुँच नहीं है। डेमो रिकॉर्ड इसी ब्राउज़र में सेव रहते हैं। कोई वास्तविक AI मॉडल या बैंक कनेक्शन नहीं है।')}</p><div class="info-note" style="margin-top:18px">${icon('lock')}${t('Never enter a real UPI PIN, OTP, banking password, or real payment link.','असली UPI PIN, OTP, बैंक पासवर्ड या वास्तविक भुगतान लिंक न डालें।')}</div></div><div class="card settings-group"><h2>${t('A fresh start','नई शुरुआत')}</h2><p style="color:var(--muted);font-size:12px;margin-bottom:17px">${t('Restore the original sample checks, preferences, and candidate-model state.','मूल डेमो जाँच, पसंद और मॉडल की स्थिति वापस लाएँ।')}</p>${btn(t('Reset demo data','डेमो डेटा रीसेट करें'),'confirm-reset','secondary','refresh')}</div></div>`;}
function toggleSetting(id,title,sub){return `<div class="setting-row"><div><strong>${title}</strong><p>${sub}</p></div><button class="toggle ${state[id]?'on':''}" role="switch" aria-checked="${state[id]}" aria-label="${esc(title)}" data-setting="${id}"></button></div>`;}

function analystPage(){if(page==='settings')return settings();if(page==='transactions')return transactions();if(page==='investigations')return investigation();if(page==='patterns')return patterns();if(page==='evaluation')return evaluation();return overview();}
function analystHead(title,sub,action=''){return `<div class="page-head"><div><h1>${title}</h1><p>${sub}</p></div>${action}</div>`;}
function overview(){const records=state.records;const flagged=records.filter(r=>r.risk!=='low').length,pending=records.filter(r=>['Pending review','Needs investigation'].includes(r.review)).length;return `${analystHead('A clearer picture of payment risk.','Your synthetic operations at a glance. Every number below is demo data.',`<span class="date">${icon('calendar')}${today()}</span>`)}
 <div class="info-note">${icon('info')}Live within this demo: consumer checks and analyst decisions share the same browser data. Suspicions, review labels, and cancellations remain separate.</div><div class="metric-grid">${metric('Payments assessed',records.length,'Synthetic demo transactions','transactions')}${metric('Flagged transactions',flagged,'Suspected indicators · not confirmed fraud','alert')}${metric('Pending reviews',pending,'Includes cases needing investigation','search')}${metric('Warning rate',Math.round(flagged/Math.max(records.length,1)*100)+'%','Median 48 ms · p95 112 ms · illustrative','clock')}</div>
 <div class="chart-grid"><section class="card chart-card"><div class="chart-title"><h2>Transaction & alert trends</h2><div class="legend"><span><i></i>Assessments</span><span><i class="amber"></i>Alerts</span></div></div><svg class="trend-chart" viewBox="0 0 560 180" role="img" aria-label="Illustrative 7-day trend: assessed payments 120, 145, 131, 180, 165, 205, 224; alerts 12, 18, 16, 25, 21, 29, 31."><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#72ac941f"/><stop offset="1" stop-color="#72ac9400"/></linearGradient></defs>${[20,60,100,140].map((y,i)=>`<path class="gridline" d="M30 ${y}H550"/><text x="0" y="${y+4}">${[240,160,80,0][i]}</text>`).join('')}<path d="M35 85 120 72 205 80 290 52 375 60 460 38 545 25V140H35Z" fill="url(#area)"/><path class="line" d="M35 85 120 72 205 80 290 52 375 60 460 38 545 25"/><path class="alert-line" d="M35 132 120 127 205 129 290 122 375 125 460 119 545 117"/>${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map((v,i)=>`<text x="${29+i*85}" y="169">${v}</text>`).join('')}</svg><small style="color:var(--muted);font-size:9px">Illustrative historical chart · separate from the interactive demo totals above</small></section>
 <section class="card chart-card"><div class="chart-title"><h2>Suspected fraud categories</h2><small>Illustrative mix</small></div><div class="distribution"><div class="donut" role="img" aria-label="Illustrative category distribution: refund deception 38%, QR substitution 26%, fake KYC 20%, other 16%"><span>4<small>demo categories</small></span></div><div class="donut-legend">${[['Refund deception','38%','#267e72'],['QR substitution','26%','#7ba392'],['Fake KYC','20%','#d5b37a'],['Other signals','16%','#b4c6bd']].map(([a,b,c])=>`<div><i style="background:${c}"></i>${a}<b>${b}</b></div>`).join('')}</div></div></section></div>
 <div class="section-heading"><h2>Review queue <span style="color:var(--muted);font-weight:400">· ${pending} cases</span></h2><button class="text-link" data-page="transactions">View all transactions ${icon('arrow')}</button></div><div class="card table-scroll">${analystTable(records.filter(r=>['Pending review','Needs investigation'].includes(r.review)).slice(0,5),true)}</div>
 <div class="section-heading"><h2>Patterns worth a closer look</h2><button class="text-link" data-page="patterns">Open Pattern Lab ${icon('arrow')}</button></div><button class="scenario-card" data-page="patterns" style="background:white;margin-top:0">${icon('lab')}<span><strong>Refundable job-onboarding deposits</strong><small>Held-out demo family · shared “refundable deposit” wording · analyst review required</small></span>${icon('arrow','arrow')}</button><div class="stat-row"><span>Analyst-labelled fraudulent <strong>${records.filter(r=>r.review==='Fraudulent').length}</strong></span><span>User cancellations <strong>${records.filter(r=>r.action==='Cancelled').length}</strong></span><span>Cancelled amounts are not measured fraud losses prevented.</span></div>${footer()}`;}
function metric(label,value,note,ic){return `<div class="card metric"><div class="metric-label">${label}${icon(ic)}</div><div class="metric-value">${value}</div><small>${note}</small></div>`;}
function filteredRecords(){return state.records.filter(r=>{const q=filter.query.toLowerCase();const withinDate=filter.date==='all'||Date.now()-r.time<Number(filter.date)*864e5;return withinDate&&(!q||[r.id,r.customer,r.recipient,r.category,r.account].some(v=>String(v).toLowerCase().includes(q)))&&(filter.risk==='all'||r.risk===filter.risk)&&(filter.category==='all'||r.category===filter.category)&&(filter.status==='all'||r.review===filter.status)&&(!filter.min||r.amount>=Number(filter.min))&&(!filter.max||r.amount<=Number(filter.max));}).sort((a,b)=>{const x=a[sort.by],y=b[sort.by];return (typeof x==='number'?x-y:String(x).localeCompare(String(y)))*sort.direction;});}
function transactions(){const result=filteredRecords();return `${analystHead('Every payment has a story.','Search synthetic transactions and investigate the signals behind an assessment.',btn('Export demo data','export','secondary','download'))}<div class="filters"><input class="search" id="analyst-search" data-filter="query" type="search" value="${esc(filter.query)}" placeholder="Search ID, customer, or recipient…" aria-label="Search transactions"><select data-filter="date" aria-label="Date range">${[['all','All dates'],['1','Last 24 hours'],['7','Last 7 days'],['30','Last 30 days']].map(([id,label])=>`<option value="${id}" ${filter.date===id?'selected':''}>${label}</option>`).join('')}</select><select data-filter="risk" aria-label="Risk level">${[['all','All risk levels'],['high','High risk'],['medium','Needs review'],['low','No strong indicators']].map(([id,label])=>`<option value="${id}" ${filter.risk===id?'selected':''}>${label}</option>`).join('')}</select><select data-filter="category" aria-label="Suspected category"><option value="all">All categories</option>${[...new Set(state.records.map(r=>r.category))].map(c=>`<option ${filter.category===c?'selected':''}>${esc(c)}</option>`).join('')}</select><select data-filter="status" aria-label="Review status">${['all','Pending review','Needs investigation','Fraudulent','Legitimate'].map(c=>`<option value="${c}" ${filter.status===c?'selected':''}>${c==='all'?'All review statuses':c}</option>`).join('')}</select><input class="amount-filter" data-filter="min" type="number" min="0" value="${esc(filter.min)}" aria-label="Minimum amount" placeholder="Min ₹"><input class="amount-filter" data-filter="max" type="number" min="0" value="${esc(filter.max)}" aria-label="Maximum amount" placeholder="Max ₹"><button class="icon-btn" data-action="clear-filters" aria-label="Clear filters">${icon('refresh')}</button></div><div class="card table-scroll" id="transactions-results">${transactionsResults(result)}</div>${footer()}`;}
function transactionsResults(result){return `${analystTable(result)}<div class="table-bottom"><span>${result.length} synthetic transaction${result.length===1?'':'s'}</span><span>Select a row to investigate ${icon('chevron')}</span></div>`;}
function analystTable(records,compact=false){if(!records.length)return `<div class="empty">${icon('search')}<h2>No matching transactions.</h2><p>Try another filter or clear your search.</p>${btn('Clear filters','clear-filters','secondary')}</div>`;const header=(label,by)=>`<th scope="col" aria-sort="${sort.by===by?(sort.direction===1?'ascending':'descending'):'none'}"><button data-sort="${by}">${label}${icon('sort')}</button></th>`;return `<table class="analyst-table"><thead><tr>${header('Transaction','time')}${header('Customer','customer')}${header('Recipient','recipient')}${header('Amount','amount')}<th>Risk level</th><th>Suspected category</th>${compact?'':'<th>Top reason</th>'}<th>Review status</th></tr></thead><tbody>${records.map(r=>`<tr data-investigate="${r.id}" role="button" tabindex="0" aria-label="Investigate ${r.id} ${esc(r.recipient)}"><td><strong>${r.id}</strong><small>${dateText(r.time)}</small></td><td>${esc(r.customer)}</td><td>${esc(r.recipient)}<small>${esc(r.action)}</small></td><td class="amount">${money(r.amount)}</td><td>${pill(r.invalidated?'neutral':r.risk,r.invalidated?'Invalidated':null)}</td><td>${esc(r.category)}</td>${compact?'':`<td style="white-space:normal;min-width:190px;max-width:240px;line-height:1.6">${esc(r.evidence[0])}</td>`}<td>${pill(r.review==='Fraudulent'?'high':r.review==='Legitimate'?'low':'neutral',r.review)}</td></tr>`).join('')}</tbody></table>`;}
function investigation(){const r=state.records.find(r=>r.id===selectedRecord)||state.records.find(r=>r.review==='Pending review')||state.records[0];if(!r)return `<div class="empty"><h1>No cases yet.</h1><p>Run a consumer check to create a case.</p>${btn('Open consumer app','go-consumer')}</div>`;selectedRecord=r.id;const s=scenarios.find(s=>s.id===r.scenario)||scenarios[0];return `${analystHead(`Investigation ${esc(r.id)}`,'Synthetic case · separate observed evidence from message interpretation.',btn('All transactions','all-transactions','secondary','back'))}<div class="investigation-grid"><section class="card investigation-card"><h2>Transaction & customer</h2>${pill(r.risk)}<div class="money-value" style="font-size:31px">${money(r.amount)}</div>${[['Customer',r.customer],['Demo recipient',r.recipient],['Destination',r.account],['Payment direction','Outgoing · INR'],['Assessment time',dateText(r.time)],['User action',r.action],['Review status',r.review],['Customer history',r.scenario==='merchant'||r.scenario==='change'?'Prior synthetic merchant interaction':'First synthetic payment to recipient']].map(([label,value])=>`<div class="detail-pair"><small>${label}</small><strong>${esc(value)}</strong></div>`).join('')}<div class="model-note">Session: ${esc(r.session)}<br>${r.invalidated?'Assessment invalidated after payment details changed.':'Assessment bound to amount, recipient, currency and session.'}</div></section>
 <section class="card investigation-card"><h2>Evidence timeline</h2><ol class="timeline"><li><small>${dateText(r.time-5000)}</small><span class="evidence-tag">Observed · supplied text</span>Associated message received<p>“${esc(r.message||'No message provided.')}”</p></li><li><small>${dateText(r.time-3500)}</small><span class="evidence-tag">Observed</span>Demo QR or link parsed<p>${esc(r.account)} · ${money(r.amount)} · outgoing</p></li><li><small>${dateText(r.time-2000)}</small><span class="evidence-tag">Observed</span>Payment prepared<p>No real payment initiated.</p></li><li><small>${dateText(r.time)}</small><span class="evidence-tag">${r.risk==='low'?'Observed':'Observed + inferred'}</span>Risk assessment completed${r.evidence.map(e=>`<p><span class="evidence-tag ${/appears|interpretation/i.test(e)?'inferred':/unavailable/i.test(e)?'unavailable':''}">${/appears|interpretation/i.test(e)?'Inferred':/unavailable/i.test(e)?'Unavailable':'Observed'}</span>${esc(e)}</p>`).join('')}</li><li><small>After assessment</small>Assessment ${r.risk==='low'?'preview':'warning'} displayed<p>${r.invalidated?'Previous result invalidated.':r.category}</p></li><li><small>${dateText(r.time)}</small><span class="evidence-tag">Observed demo action</span>User action: ${esc(r.action)}</li></ol></section>
 <section class="card investigation-card"><h2>Decision explanation</h2><h3 style="font-size:11px">Triggered checks</h3>${evidenceList(r.evidence)}<h3 style="font-size:11px;margin-top:20px">Illustrative feature contributions</h3>${[['Intent / direction mismatch',r.risk==='high'?72:12],['Recipient reference',r.reference==='mismatch'?88:r.reference==='unavailable'?45:8],['New recipient signal',r.scenario==='merchant'?5:39]].map(([label,n])=>`<div class="contribution"><span>${label}</span><span>${n}%</span><div class="bar"><i style="width:${n}%"></i></div></div>`).join('')}<div class="model-note"><span class="evidence-tag unavailable">Unavailable</span>${r.reference==='unavailable'?'Independently verified merchant identity.':'Live merchant registry or bank confirmation.'}<br>Actual device telemetry and private app data.<br><br>Model: hybrid-demo-v1.3 · simulated scoring<br>Feature contributions are illustrative, not measured.<br>Review labels are analyst decisions on synthetic cases.</div><div class="review-buttons">${btn('Mark fraudulent','review-fraudulent','danger')}${btn('Mark legitimate','review-legitimate','secondary')}${btn('Needs investigation','review-investigate','secondary')}</div><p style="font-size:10px;color:var(--muted);margin-top:15px">Current review: <strong>${esc(r.review)}</strong></p></section></div>${footer()}`;}
function patterns(){return `${analystHead('Find the pattern behind the payment.','Explore synthetic clusters. Analyst labels inform a simulated candidate update.')}<div class="evaluation-note">Pattern Lab is an illustrative workflow. No real training, production model change, or automatic deployment occurs.</div><div class="cluster-grid"><section class="card cluster featured"><span class="pill medium">Held-out demo pattern</span><h2>Refundable job-onboarding deposit</h2><p>A new job offer requests an upfront payment described as refundable. The employer’s identity is unavailable.</p><div class="cluster-meta"><span>“refundable deposit”</span><span>First-time recipient</span><span>Job offer</span></div><div class="detail-pair"><small>Interactive example cases</small><strong>${state.records.filter(r=>r.scenario==='job').length} synthetic case(s)</strong></div><div class="assessment-actions">${btn('Review examples','pattern-examples','full','','')}${btn(state.candidate==='prepared'?'Candidate prepared':'Prepare candidate update','prepare-candidate','secondary full','lab')}</div></section><section class="card cluster"><span class="pill high">Familiar pattern</span><h2>Refund language, outgoing payments</h2><p>Supplied messages appear to promise a refund while the prepared payment sends money to a new recipient.</p><div class="cluster-meta"><span>“receive refund”</span><span>Outgoing payment</span></div><div class="detail-pair"><small>Analyst labels</small><strong>${state.records.filter(r=>r.scenario==='refund'&&r.review==='Fraudulent').length} labelled fraudulent</strong></div><div class="assessment-actions">${btn('Explore refund cases','refund-cases','secondary full')}</div></section><section class="card cluster"><span class="pill high">Familiar pattern</span><h2>Shop QR, unrelated destination</h2><p>The recipient account differs from the independently saved shop destination. QR display names cannot validate themselves.</p><div class="cluster-meta"><span>Account mismatch</span><span>Merchant reference</span></div><div class="detail-pair"><small>Evidence source</small><strong>Independent synthetic merchant record</strong></div><div class="assessment-actions">${btn('Explore QR cases','qr-cases','secondary full')}</div></section></div><div class="card form-card" style="margin-top:24px"><h2>Candidate update workflow</h2><div class="stepper" style="margin:24px 0"><div class="step active"><b>1</b>Review examples</div><span></span><div class="step ${state.candidate==='prepared'?'active':''}"><b>2</b>Prepare candidate</div><span></span><div class="step"><b>3</b>Compare evaluation</div></div><p style="font-size:12px;color:var(--muted)">${state.candidate==='prepared'?'Your simulated candidate is ready. Compare its illustrative evaluation with the original model.':'Review example evidence and labels, then prepare a simulated candidate for comparison.'}</p><div class="button-row">${btn('Compare evaluation','compare-evaluation',state.candidate==='prepared'?'':'secondary','chart')}</div></div>${footer()}`;}
function evaluation(){return `${analystHead('Evaluate the whole picture.','Illustrative model comparisons on a synthetic test set.',state.candidate==='prepared'?'<span class="pill low">Candidate available · simulated</span>':'<span class="pill neutral">Original demo model</span>')}<div class="evaluation-note"><strong>Illustrative values — not measured performance.</strong> No actual model training or evaluation is implemented. Test-set size: 10,000 synthetic examples · fraud prevalence: 10% · fixed held-out split.</div><div class="card table-scroll"><table class="eval-table"><thead><tr><th>Metric</th><th>Rules-only baseline</th><th>Transaction-only model</th><th>Full hybrid system</th></tr></thead><tbody>${[['Precision','82.0%','88.0%','94.0%'],['Recall','61.0%','74.0%','91.0%'],['False-positive rate','1.49%','1.12%','0.64%'],['PR-AUC','0.72','0.83','0.95'],['Median scoring latency','12 ms','31 ms','48 ms'],['p95 scoring latency','28 ms','76 ms','112 ms']].map(row=>`<tr>${row.map((c,i)=>`<${i?'td':'th'} ${i===3?'class="best"':''}>${c}</${i?'td':'th'}>`).join('')}</tr>`).join('')}</tbody></table></div><div class="eval-bottom"><section class="card chart-card"><h2>Per-category recall</h2><p style="font-size:10px;color:var(--muted);margin-top:7px">Full hybrid system · illustrative</p>${[['Refund deception',96],['QR substitution',94],['Fake KYC',90],['Remote-access risk',84]].map(([label,n])=>`<div class="contribution"><span>${label}</span><span>${n}%</span><div class="bar" style="height:7px"><i style="width:${n}%"></i></div></div>`).join('')}</section><section class="card chart-card"><h2>Confusion matrix</h2><p style="font-size:10px;color:var(--muted);margin-top:7px">Full hybrid · threshold 0.5 · illustrative</p><div class="matrix"><div><strong>910</strong><small>True positives</small></div><div><strong>58</strong><small>False positives</small></div><div><strong>90</strong><small>False negatives</small></div><div><strong>8,942</strong><small>True negatives</small></div></div></section></div><section class="card form-card" style="margin-top:23px"><div class="section-heading" style="margin-top:0"><h2>Held-out family: refundable onboarding deposits</h2>${pill('neutral','Simulated comparison')}</div><p style="font-size:11px;color:var(--muted);margin-bottom:18px">Illustrative family slice: 200 synthetic fraudulent requests plus 1,800 legitimate requests. Candidate preparation is simulated; the held-out evaluation slice is not used as training data.</p>${state.candidate==='prepared'?`<div class="table-scroll"><table class="eval-table"><thead><tr><th>Metric</th><th>Original v1.3</th><th>Candidate v1.4</th></tr></thead><tbody><tr><td>Family recall</td><td>42.0%</td><td class="best">81.0%</td></tr><tr><td>Precision</td><td>85.7%</td><td class="best">92.0%</td></tr><tr><td>False-positive rate</td><td>0.78%</td><td>0.78%</td></tr><tr><td>True / false positives</td><td>84 / 14</td><td>162 / 14</td></tr><tr><td>False / true negatives</td><td>116 / 1,786</td><td>38 / 1,786</td></tr></tbody></table></div><div class="info-note" style="margin-top:18px">${icon('lock')}Candidate saved for comparison only. No production model is deployed by this prototype.</div>`:`<div class="empty" style="padding:25px">${icon('lab')}<h2>No candidate prepared yet.</h2><p>Start with the held-out examples in Pattern Lab.</p>${btn('Open Pattern Lab','open-patterns','secondary')}</div>`}</section>${footer()}`;}

function openModal(title,subtitle,body){modalTrigger=document.activeElement;$('#overlay').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><header class="modal-head"><div><h2 id="dialog-title">${title}</h2><p>${subtitle}</p></div><button class="icon-btn" aria-label="Close dialog" data-action="close-modal">${icon('x')}</button></header><div class="modal-body">${body}</div></section></div>`;document.body.style.overflow='hidden';$('#overlay button, #overlay input, #overlay select')?.focus();}
function closeModal(restore=true){if(!$('#overlay').innerHTML)return;$('#overlay').innerHTML='';document.body.style.overflow='';if(restore&&modalTrigger?.isConnected)modalTrigger.focus();}
function scenarioModal(){openModal(t('Let’s try a payment check.','एक भुगतान जाँच आज़माएँ।'),t('Synthetic scenarios. Real clarity. No money moves.','डेमो उदाहरण। स्पष्ट जानकारी। कोई वास्तविक भुगतान नहीं।'),`<div class="scenario-list">${scenarios.map((s,i)=>`<button class="scenario-option" data-scenario="${s.id}"><span class="number">0${i+1}</span><span><strong>${esc(s.name)}</strong><small>${esc(s.summary)}</small></span>${icon('chevron')}</button>`).join('')}</div>`);}
function qrModal(){openModal(t('Demo QR scanner','डेमो QR स्कैनर'),t('Select a synthetic QR. Your camera is not accessed.','एक डेमो QR चुनें। कैमरा इस्तेमाल नहीं होता।'),`<div class="scenario-list">${[['merchant','','Sharma Medical','Matching destination · ₹450'],['merchant','proprietor','Rajesh Sharma · proprietor','Approved name variation · matching account'],['qr','','Campus Canteen','Substituted destination · ₹180'],['merchant','unknown','Neighbourhood Books','Independent record unavailable']].map(([id,v,title,sub])=>`<button class="scenario-option" data-qr="${id}" data-variation="${v}"><span class="number">${icon('scan')}</span><span><strong>${title}</strong><small>${sub}</small></span>${icon('chevron')}</button>`).join('')}</div><p style="font-size:10px;color:var(--muted);margin-top:17px">A QR’s display name is never used as an independent identity reference.</p>`);}
function recordModal(id){const r=state.records.find(r=>r.id===id);if(!r)return;openModal(esc(r.recipient)+' · '+money(r.amount),dateText(r.time)+' · '+r.id,`${pill(r.invalidated?'neutral':r.risk,r.invalidated?'Assessment invalidated':null)}<div class="field-grid" style="margin:22px 0">${[['Category',r.category],['User action',r.action],['Direction','Outgoing · INR'],['Review status',r.review],['Recipient account',r.account],['Assessment time',dateText(r.time)]].map(([a,b])=>`<div class="detail-pair"><small>${a}</small><strong>${esc(b)}</strong></div>`).join('')}</div><h3>Assessment evidence</h3>${evidenceList(r.evidence)}<div class="info-note">${icon('info')}Demo assessment based only on supplied details. Message meaning is an interpretation, not a confirmed fact.</div><div class="button-row"><button class="btn secondary" data-investigate="${r.id}">Open analyst investigation ${icon('arrow')}</button></div>`);}
function readAloud(){if(!('speechSynthesis' in window)){toast(t('Read-aloud is unavailable in this browser. The full warning is displayed on screen.','इस ब्राउज़र में पढ़कर सुनाना उपलब्ध नहीं है। पूरी चेतावनी स्क्रीन पर है।'));return;}const text=$('.assessment-header h1')?.textContent+' '+($('.assessment-header p')?.textContent||'');speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang=state.language==='hi'?'hi-IN':'en-IN';u.rate=.9;u.onerror=()=>toast(t('A suitable voice is unavailable. Please read the warning on screen.','उपयुक्त आवाज़ उपलब्ध नहीं है। स्क्रीन पर चेतावनी पढ़ें।'));speechSynthesis.speak(u);}
function parseDemoLink(value){const raw=value.trim();try{const url=new URL(raw);if(url.protocol!=='https:'||url.hostname!=='pay.demo'||url.username||url.password)throw 0;const id=url.pathname.replace(/^\//,'').replace(/\/$/,'');if(!scenarios.some(s=>s.id===id))throw 0;return id;}catch{return null;}}
function readLink(value){const id=parseDemoLink(value);if(!id){formError=t('Use a supported synthetic link, for example https://pay.demo/refund. Live payment links are not supported.','एक डेमो लिंक उपयोग करें, जैसे https://pay.demo/refund। वास्तविक भुगतान लिंक उपलब्ध नहीं हैं।');page='check';mode='link';flowStep='input';render();return false;}mode='link';createFlow(id);flow.link=value.trim();render();return true;}
function captureForm(){if(!flow)return;flow.message=$('#payment-message')?.value??flow.message;flow.intent=$('input[name="intent"]:checked')?.value??flow.intent;}
function updateAction(action){const r=state.records.find(r=>r.id===assessment?.recordId);if(r)r.action=action;persist();}
function doChange(){if(!flow)return;if(assessment){const r=state.records.find(r=>r.id===assessment.recordId);if(r){r.invalidated=true;r.action='Recheck required';}assessment.invalidated=true;}flow.oldRecipient=flow.recipient;flow.recipient='Amit Personal';flow.account='amitpersonal@demo';flow.ref='mismatch';flow.reference='Saved destination: sharmamedical@demo';flow.changed=true;flowStep='changed';persist();render();window.scrollTo(0,0);}
function review(status){const r=state.records.find(r=>r.id===selectedRecord);if(!r)return;r.review=status;r.reviewedAt=Date.now();persist();render();toast(`Review saved: ${status}. Related demo views updated.`);}
function editModal(){openModal(t('Edit demo payment details','डेमो भुगतान विवरण बदलें'),t('Changing details invalidates the current check.','विवरण बदलने से वर्तमान जाँच अमान्य हो जाएगी।'),`<form id="edit-form"><label class="field-label" for="edit-amount">Amount (INR)</label><input id="edit-amount" name="amount" type="number" min="1" max="1000000" step="0.01" required value="${flow.amount}"><div class="form-row"><label class="field-label" for="edit-recipient">Recipient</label><select id="edit-recipient" name="account"><option value="sharmamedical@demo" ${flow.account==='sharmamedical@demo'?'selected':''}>Sharma Medical · sharmamedical@demo</option><option value="amitpersonal@demo" ${flow.account==='amitpersonal@demo'?'selected':''}>Amit Personal · amitpersonal@demo</option>${!['sharmamedical@demo','amitpersonal@demo'].includes(flow.account)?`<option selected value="${esc(flow.account)}">${esc(flow.recipient)} · ${esc(flow.account)}</option>`:''}</select></div><div class="button-row"><button class="btn" type="submit">Save & reassess ${icon('refresh')}</button></div></form>`);}
const actions={
 'brand':()=>{navigate(view==='consumer'?'home':'overview');},
 'go-home':()=>navigate('home'),'go-activity':()=>navigate('activity'),
 'new-check':()=>{flow=null;assessment=null;flowStep='input';mode='qr';navigate('check');},
 'scenarios':scenarioModal,'qr-picker':qrModal,'close-modal':()=>closeModal(),
 'back-input':()=>{flowStep='input';render();},'show-result':()=>{flowStep='result';render();window.scrollTo(0,0);},
 'load-link':()=>readLink($('#payment-link')?.value||''),
 'identity':()=>{flowStep='identity';render();window.scrollTo(0,0);},
 'verify':()=>{flowStep='verify';render();window.scrollTo(0,0);},
 'cancel-payment':()=>{if(!flow)return;updateAction('Cancelled');flow.outcome='Cancelled';flowStep='complete';render();window.scrollTo(0,0);},
 'complete-payment':()=>{if(!validAssessment()||assessment.risk!=='low'){toast('A current assessment is required.');flowStep='result';render();return;}updateAction('Simulated completion');flow.outcome='Simulated completion';flowStep='complete';render();window.scrollTo(0,0);},
 'leave-review':()=>{updateAction('Reviewed');navigate('home');toast('Demo check saved for analyst review.');},
 'change-recipient':doChange,'reassess':analyse,'read-aloud':readAloud,'edit-details':editModal,
 'stop-sharing':()=>{flow.stoppedSharing=true;flow.id='remote-stopped';flow.risk='medium';flow.category='Identity unavailable';flow.ref='unavailable';flow.session=crypto.randomUUID();analyse();},
 'open-analyst-record':()=>{selectedRecord=assessment?.recordId;view='analyst';navigate('investigations');},
 'all-transactions':()=>navigate('transactions'),'go-consumer':()=>{view='consumer';navigate('home');},
 'review-fraudulent':()=>review('Fraudulent'),'review-legitimate':()=>review('Legitimate'),'review-investigate':()=>review('Needs investigation'),
 'clear-filters':()=>{filter={query:'',risk:'all',category:'all',status:'all',min:'',max:'',date:'all'};render();},
 'refund-cases':()=>{filter={query:'',risk:'all',category:'Refund deception',status:'all',min:'',max:'',date:'all'};navigate('transactions');},
 'qr-cases':()=>{filter={query:'',risk:'all',category:'QR substitution',status:'all',min:'',max:'',date:'all'};navigate('transactions');},
 'open-patterns':()=>navigate('patterns'),
 'pattern-examples':()=>{const examples=state.records.filter(r=>r.scenario==='job');openModal('Review the unfamiliar pattern','Synthetic examples · interpretations require analyst judgement.',`<div class="notice-total">${examples.length} example(s) · ${examples.filter(r=>r.review==='Fraudulent').length} analyst-labelled fraudulent</div>${examples.map(r=>`<button class="scenario-option" data-investigate="${r.id}"><span class="number">${icon('briefcase')}</span><span><strong>${esc(r.id)} · ${money(r.amount)}</strong><small>${esc(r.message)}<br>Review label: ${esc(r.review)}</small></span>${icon('chevron')}</button>`).join('')}<div class="info-note" style="margin-top:18px">${icon('info')}Shared wording: “refundable”, “onboarding deposit”, “offer letter”. Identity information is unavailable.</div><div class="button-row">${btn('Prepare candidate update','prepare-candidate','','lab')}</div>`);},
 'prepare-candidate':async()=>{if(state.candidate==='prepared'){closeModal();navigate('evaluation');return;}openModal('Prepare a candidate update','Simulation only · no real training or deployment.',`<p style="font-size:12px;color:var(--muted);line-height:1.9">Include the refundable job-onboarding deposit pattern as an illustrative candidate rule. Analyst labels remain attached to their cases. Evaluation uses a separate held-out synthetic slice.</p><div class="button-row">${btn('Prepare simulated candidate','confirm-candidate','','lab')}</div>`);},
 'confirm-candidate':async()=>{openModal('Preparing a simulated candidate','No real training is taking place.',`<div class="loading" style="padding:35px"><div class="spinner"></div><p>Preparing illustrative comparison…</p></div>`);await new Promise(r=>setTimeout(r,1200));state.candidate='prepared';persist();if($('#overlay').innerHTML)closeModal();if(view==='analyst')navigate('evaluation');toast('Simulated candidate prepared. No model deployed.');},
 'compare-evaluation':()=>navigate('evaluation'),
 'confirm-reset':()=>openModal(t('Reset this demo?','डेमो रीसेट करें?'),t('This affects both experiences in this browser.','इस ब्राउज़र में दोनों अनुभव रीसेट होंगे।'),`<p style="font-size:12px;color:var(--muted)">${t('Your added checks, review decisions, language preferences, and simulated candidate will be replaced with the original sample data.','नई जाँच, समीक्षा, भाषा पसंद और डेमो उम्मीदवार को मूल उदाहरण से बदल दिया जाएगा।')}</p><div class="button-row">${btn(t('Keep my data','डेटा रखें'),'close-modal','secondary')}${btn(t('Reset demo','डेमो रीसेट करें'),'reset','danger')}</div>`),
 'reset':()=>{run++;state=seed();persist();flow=null;assessment=null;selectedRecord=null;flowStep='input';activityFilter='all';filter={query:'',risk:'all',category:'all',status:'all',min:'',max:'',date:'all'};closeModal();render();toast('Original demo data restored.');},
 'safety':()=>openModal(t('A little payment wisdom.','भुगतान से जुड़ी कुछ बातें।'),t('Simple things to check before you decide.','फैसला करने से पहले कुछ आसान जाँच।'),`<div class="notification-item">${icon('arrow')}<div><strong>${t('Look at the direction.','दिशा देखें।')}</strong><p>${t('A payment that sends money cannot also receive a refund. Compare the message with the payment details.','पैसे भेजने वाला भुगतान रिफंड नहीं दिलाता। संदेश और विवरण की तुलना करें।')}</p></div></div><div class="notification-item">${icon('store')}<div><strong>${t('Confirm the destination independently.','खाते की स्वतंत्र पुष्टि करें।')}</strong><p>${t('A name displayed in a QR is not independent verification. Ask the shop to confirm its account through a separate channel.','QR का नाम स्वतंत्र सत्यापन नहीं है। अलग माध्यम से दुकान के खाते की पुष्टि करें।')}</p></div></div><div class="notification-item">${icon('refresh')}<div><strong>${t('Details changed? Check again.','विवरण बदले? फिर जाँचें।')}</strong><p>${t('A previous assessment applies only to the details you reviewed. A new recipient or amount requires a fresh check.','पिछला आकलन केवल पुराने विवरण पर लागू है। नए प्राप्तकर्ता या राशि के लिए फिर से जाँच करें।')}</p></div></div><div class="button-row">${btn(t('Try a demo scenario','एक डेमो आज़माएँ'),'scenarios')}</div>`),
 'notifications':()=>openModal('Your demo updates','Updates from the synthetic activity in this browser.',`<div class="notification-item">${icon('shield')}<div><strong>Your payment companion is ready.</strong><p>Start a demo check to compare what you expect with what a payment does.</p></div></div><div class="notification-item">${icon('search')}<div><strong>${state.records.filter(r=>r.review==='Pending review').length} demo cases awaiting analyst review.</strong><p>Switch to the analyst dashboard to inspect their evidence.</p></div></div><div class="button-row">${btn('Close','close-modal','secondary')}</div>`),
 'export':()=>{const data=state.records.map(r=>({id:r.id,timestamp:new Date(r.time).toISOString(),customer:r.customer,recipient:r.recipient,amount:r.amount,currency:r.currency,risk:r.risk,category:r.category,review:r.review,userAction:r.action}));const url=URL.createObjectURL(new Blob([JSON.stringify({notice:'Synthetic demo data only. No real payments.',transactions:data},null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='upi-guard-demo-transactions.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Synthetic demo transactions exported.');}
};
document.addEventListener('click',e=>{
 const el=e.target.closest('[data-action],[data-page],[data-view],[data-start],[data-mode],[data-scenario],[data-qr],[data-record],[data-investigate],[data-language],[data-setting],[data-activity-filter],[data-sort]');if(!el){if(e.target.classList.contains('modal-backdrop'))closeModal();return;}
 if(el.disabled)return;
 if(el.dataset.action){e.preventDefault();actions[el.dataset.action]?.();}
 else if(el.dataset.page)navigate(el.dataset.page);
 else if(el.dataset.view){view=el.dataset.view;navigate(view==='consumer'?'home':'overview');}
 else if(el.dataset.start){flow=null;assessment=null;flowStep='input';mode=el.dataset.start;navigate('check');}
 else if(el.dataset.mode){captureForm();mode=el.dataset.mode;formError='';render();}
 else if(el.dataset.scenario)createFlow(el.dataset.scenario);
 else if(el.dataset.qr){mode='qr';createFlow(el.dataset.qr,el.dataset.variation);}
 else if(el.dataset.record)recordModal(el.dataset.record);
 else if(el.dataset.investigate){selectedRecord=el.dataset.investigate;view='analyst';navigate('investigations');}
 else if(el.dataset.language){state.language=el.dataset.language;persist();render();}
 else if(el.dataset.setting){state[el.dataset.setting]=!state[el.dataset.setting];persist();render();}
 else if(el.dataset.activityFilter){activityFilter=el.dataset.activityFilter;render();}
 else if(el.dataset.sort){sort={by:el.dataset.sort,direction:sort.by===el.dataset.sort?-sort.direction:1};if(page==='transactions')$('#transactions-results').innerHTML=transactionsResults(filteredRecords());else render();}
});
document.addEventListener('change',e=>{if(e.target.id==='request-select'){const id=e.target.value;if(id)createFlow(id);else{flow=null;assessment=null;render();}}if(e.target.dataset.filter){filter[e.target.dataset.filter]=e.target.value;$('#transactions-results').innerHTML=transactionsResults(filteredRecords());}});
document.addEventListener('input',e=>{if(e.target.dataset.filter){filter[e.target.dataset.filter]=e.target.value;$('#transactions-results').innerHTML=transactionsResults(filteredRecords());}});
document.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='quick-form'){const value=new FormData(e.target).get('link');if(!value.trim()){toast(t('Paste a demo link, or try a scenario.','डेमो लिंक पेस्ट करें या एक डेमो चुनें।'));$('#quick-link').focus();return;}readLink(value);}
 else if(e.target.id==='check-form'){if(mode==='link'){const value=$('#payment-link').value;if(!flow||flow.link!==value.trim()){const message=$('#payment-message').value;if(!readLink(value))return;if(message.trim())flow.message=message;}}captureForm();analyse();}
 else if(e.target.id==='edit-form'){const f=new FormData(e.target),amount=Number(f.get('amount')),account=f.get('account');if(!Number.isFinite(amount)||amount<=0||amount>1000000)return;const unchanged=amount===flow.amount&&account===flow.account;if(unchanged){closeModal();toast('Details are unchanged. Your assessment still applies.');return;}const r=state.records.find(r=>r.id===assessment?.recordId);if(r){r.invalidated=true;r.action='Recheck required';}if(assessment)assessment.invalidated=true;flow.amount=amount;if(account!==flow.account){flow.oldRecipient=flow.recipient;flow.account=account;flow.recipient=account==='sharmamedical@demo'?'Sharma Medical':'Amit Personal';flow.changed=true;flow.ref=account==='sharmamedical@demo'?'match':'mismatch';}persist();closeModal();analyse();}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();return;}if((e.key==='Enter'||e.key===' ')&&e.target.matches('tr[data-record],tr[data-investigate]')){e.preventDefault();e.target.click();}if(e.key==='Tab'&&$('#overlay').innerHTML){const focusables=[...$('#overlay').querySelectorAll('button,input,select,textarea,a[href]')].filter(el=>!el.disabled);const first=focusables[0],last=focusables.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
window.addEventListener('storage',e=>{if(e.key===key&&e.newValue){try{const incoming=JSON.parse(e.newValue);if(Array.isArray(incoming.records)){state=incoming;render();}}catch{}}});
render();
